import { getAllProducts } from '../lib/db';
import { revalidateTag } from 'next/cache';

const PRODUCTS_CACHE_TAG = 'products';

type Product = {
  id: number;
  name: string;
  price: number;
};

export default function Page() {
  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px' }}>
      <h1>Product Listing</h1>
      <p style={{ color: '#666', marginBottom: '20px' }}>
        This page demonstrates efficient data caching with selective invalidation using the 
        <code>'use cache'</code> directive and cache tags.
      </p>
      <ProductList />
      <CacheInvalidationForm />
    </div>
  );
}

async function ProductList() {
  'use cache';
  const products = await getAllProducts() as Product[];
  return (
    <div>
      <h2>Products</h2>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {products.map((product: Product) => (
          <li key={product.id} style={{ 
            padding: '12px', 
            margin: '8px 0', 
            border: '1px solid #ddd', 
            borderRadius: '4px',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center'
          }}>
            <span style={{ fontWeight: '500' }}>{product.name}</span>
            <span style={{ color: '#28a745', fontWeight: 'bold' }}>${product.price}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

function CacheInvalidationForm() {
  async function invalidateCache() {
    'use server';
    revalidateTag(PRODUCTS_CACHE_TAG);
  }

  return (
    <div style={{ marginTop: '30px', padding: '20px', backgroundColor: '#f8f9fa', borderRadius: '8px' }}>
      <h3 style={{ marginTop: 0 }}>Cache Management</h3>
      <p style={{ fontSize: '14px', color: '#666' }}>
        Click below to invalidate the products cache and force a fresh data fetch.
        This demonstrates selective cache invalidation for dynamic data updates.
      </p>
      <form action={invalidateCache}>
        <button type="submit" style={{
          padding: '10px 20px',
          fontSize: '16px',
          backgroundColor: '#007bff',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          cursor: 'pointer'
        }}>
          Refresh Products Cache
        </button>
      </form>
    </div>
  );
}

